-- 1. Enable FDW
CREATE EXTENSION IF NOT EXISTS postgres_fdw;

-- 2. Define remote server
CREATE SERVER remote_billing_server
    FOREIGN DATA WRAPPER postgres_fdw
    OPTIONS (host 'billing-db.internal', port '5432', dbname 'billing');

-- 3. Map local user credentials to remote user
CREATE USER MAPPING FOR CURRENT_USER
    SERVER remote_billing_server
    OPTIONS (user 'billing_reader', password 'secret');

-- 4. Import foreign schema tables
IMPORT FOREIGN SCHEMA public LIMIT TO (invoices, subscriptions)
FROM SERVER remote_billing_server INTO public;

-- 5. Query remote invoices directly!
SELECT * FROM invoices WHERE amount > 500;
